const amounts = pairs => pairs.map(([id,quantity])=>({id,quantity}));
const creators = {terapia:'Paulo Oliveira · Terapia no Fogo',jamon:'ChefeJamon',receituando:'Receituando Master'};
function recipe(creator, slug, video, publishedAt, content, adaptation) {
  const publicMethod = (creator==='jamon' && video!=='G_l0Ou4HkxQ') || video==='ytKCkQzxdDI';
  return {
    id:`criador-${creator}-${slug}`, diet:'all', ...content,
    ingredients:amounts(content.ingredients),
    source:{creator,url:`https://www.youtube.com/watch?v=${video}`,credit:creators[creator],publishedAt,checkedAt:'2026-10-20',
      adaptation:`Doses por pessoa e quantidades não especificadas na publicação definidas por nós. ${publicMethod?'Preparação pública resumida e adaptada por nós. ':'Ingredientes verificados na descrição pública; preparação escrita por nós como adaptação para o planeador. '}${adaptation}`},
  };
}

